/** A deterministic first render; like upstream, the interval continues in hidden tabs. */
export function useGraphNow(interval = 1000) {
  const now = ref<number | null>(null)
  let id: ReturnType<typeof setInterval> | undefined
  onMounted(() => {
    now.value = Date.now()
    id = setInterval(() => {
      now.value = Date.now()
